#![allow(unused_imports)]
use vstd::prelude::*;

//----------------------------------------------------------------------------
// pure helper: is this an ASCII letter?
//----------------------------------------------------------------------------
#[verifier(spec)]
fn is_ascii_alpha(c: char) -> bool {
    ('a' <= c && c <= 'z') ||
    ('A' <= c && c <= 'Z')
}

//----------------------------------------------------------------------------
// Implementation of check_if_last_char_is_a_letter
//----------------------------------------------------------------------------
fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // We will track the last seen character in `last`
    // and the one right before it in `prev`.
    let mut prev: Option<char> = None;
    let mut last: Option<char> = None;
    for c in txt.chars() {
        prev = last;
        last = Some(c);
    }

    // Now post‐loop, `last` is the actual last char if any,
    // and `prev` is the one before it (or None if the string
    // had 0 or 1 characters).
    match last {
        None => {
            // empty string fails condition (1)
            false
        }
        Some(lc) if !is_ascii_alpha(lc) => {
            // last character not ASCII alpha fails (2)
            false
        }
        Some(_lc) => {
            // last is ASCII alpha; check (3):
            // either it was the only character (prev=None)
            // or the preceding char was a space.
            match prev {
                None     => true,
                Some(pc) => pc == ' ',
            }
        }
    }
}